window.BOOK={"key":"jawharmaknun","app":"mutoon-jawharmaknun","lsk":"mutoon_jawharmaknun_v1","prefix":"ja_","title":"الجوهر المكنون","sub":"الجوهر المكنون في صدف الثلاثة الفنون: المعاني والبيان والبديع · عبد الرحمن الأخضري (ت ٩٨٣هـ) · ٢٩١ بيتًا","poems":[{"id":"jawharmaknun","title":"الجوهر المكنون","nazim":"أبو زيد عبد الرحمن بن محمد الصغير الأخضري","death":"ت ٩٨٣هـ","meter":"الرجز","source":"تكوين الراسخين: الجوهر المكنون (ضبط أبي أمير الشافعي)","srcUrl":"https://takw.in/lughah/balaghah/aljawhar-almaknoon","note":"النص المشكول من «تكوين الراسخين» (ضبط أبي أمير الشافعي، ٢٩١ بيتًا)، قوبل آليًّا كلمةً كلمة بمتن الشاملة الذهبية وبأبيات «اللب المصون» للمقتدي وبشرح الحازمي. وأُثبتت رواية المتن المتداول في ٣٩ شطرًا اتفق عليها المتن والمقتدي (ووافقهما الحازمي غالبًا) أو كان ما في الأصل خطأً ظاهرًا، وصُحّح شكل ١٢ كلمة. كل ذلك مسجّل في تقرير المصادر.","verses":[["اَلْحَمْدُ لِلهِ الْبَدِيعِ الْهَادِي","إِلَى بَيَانِ مَهْيَعِ الرَّشَادِ"],["أَمَدَّ أَرْبَابَ النُّهَى وَرَسَمَا","شَمْسَ الْبَيَانِ فِي صُدُورِ الْعُلَمَا"],["فَأَبْصَرُوا مُعْجِزَةَ الْقُرْآنِ","وَاضِحَةً بِسَاطِعِ الْبُرْهَانِ"],["وَشَاهَدُوا مَطَالِعَ الْأَنْوَارِ","وَمَا احْتَوَتْ عَلَيْهِ مِنْ أَسْرَارِ"],["فَنَزَّهُوا الْقُلُوبَ فِي رِيَاضِهِ","وَأَوْرَدُوا الْفِكْرَ عَلَى حِيَاضِهِ"],["ثُمَّ صَلَاةُ اللهِ مَا تَرَنَّمَا","حَادٍ يَسُوقُ الْعِيسَ فِي أَرْضِ الْحِمَى"],["عَلَى نَبِيِّنَا الْحَبِيبِ الْهَادِي","أَجَلِّ كُلِّ نَاطِقٍ بِالضَّادِ"],["مُحَمَّدٍ سَيِّدِ خَلْقِ اللهِ","اَلْعَرَبِيِّ الطَّاهِرِ الْأَوَّاهِ"],["ثُمَّ عَلَى صَاحِبِهِ الصِّدِّيقِ","حَبِيبِهِ وَعُمَرَ الْفَارُوقِ"],["ثُمَّ أَبِي عَمْرٍو إِمَامِ الْعَابِدِينْ","وَسَطْوَةِ اللهِ إِمَامِ الزَّاهِدِينْ"],["ثُمَّ عَلَى بَقِيَّةِ الصَّحَابَهْ","ذَوِي التُّقَى وَالْفَضْلِ وَالْإِنَابَهْ"],["وَالْمَجْدِ وَالْفُرْصَةِ وَالْبَرَاعَهْ","وَالْحَزْمِ وَالنَّجْدَةِ وَالشَّجَاعَهْ"],["مَا عَكَفَ الْقَلْبُ عَلَى الْقُرْآنِ","مُرْتَقِيًا لِحَضْرَةِ الْعِرْفَانِ"],["هَذَا وَإِنَّ دُرَرَ الْبَيَانِ","وَغُرَرَ الْبَدِيعِ وَالْمَعَانِي"],["تَهْدِي إِلَى مَوَارِدٍ شَرِيفَهْ","وَنُبَذٍ بَدِيعَةٍ لَطِيفَهْ"],["مِنْ عِلْمِ أَسْرَارِ اللِّسَانِ الْعَرَبِي","وَدَرْكِ مَا خُصَّ بِهِ مِنْ عَجَبِ"],["لِأَنَّهُ كَالرُّوحِ لِلْإِعْرَابِ","وَهْوَ لِعِلْمِ النَّحْوِ كَاللُّبَابِ"],["وَقَدْ دَعَا بَعْضٌ مِنَ الطُّلَاَّبِ","لِرَجَزٍ يَهْدِي إِلَى الصَّوَابِ"],["فَجِئْتُهُ بَرَجَزٍ مُفِيدِ","مُهَذَّبٍ مُنَقَّحٍ سَدِيدِ"],["مُلْتَقِطًا مِنْ دُرَرِ التَّلْخِيصِ","جَوَاهِرًا بَدِيعَةَ التَّخْلِيصِ"],["سَلَكْتُ مَا أَبْدَى مِنَ التَّرْتِيبِ","وَمَا أَلَوْتُ الْجُهْدَ فِي التَّهْذِيبِ"],["سَمَّيْتُهُ بِالْجَوْهَرِ الْمَكْنُونِ","فِي صَدَفِ الثَّلَاثَةِ الْفُنُونِ"],["وَاللهَ أَرْجُو أَنْ يَكُونَ نَافِعَا","لِكُلِّ مَنْ يَقْرَؤُهُ وَرَافِعَا"],["وَأَنْ يَكُونَ فَاتِحًا لِلْبَابِ","لِجُمْلَةِ الْإِخْوَانِ وَالْأَصْحَابِ"],["فَصَاحَةُ الْمُفْرَدِ أَنْ يَخْلُصَ مِنْ","تَنَافُرٍ غَرَابَةٍ خُلْفٍ زُكِنْ"],["وَفِي الْكَلَامِ مِنْ تَنَافُرِ الْكَلِمْ","وَضَعْفِ تَأْلِيفٍ وَتَعْقِيدٍ سَلِمْ"],["وَذِي الْكَلَامِ صِفَةٌ بِهَا يُطِيقْ","تَأْدِيَةَ الْمَقْصُودِ بِاللَّفْظِ الْأَنِيقْ"],["وَجَعَلُوا بَلَاغَةَ الْكَلَامِ","طِبَاقَهُ لِمُقْتَضَى الْمَقَامِ"],["وَحَافِظٌ تَأْدِيَةَ الْمَعَانِي","عَنْ خَطَأٍ يُعْرَفُ بِالْمَعَانِي"],["وَمَا مِنَ التَّعْقِيدِ فِي الْمَعْنَى يَقِي","لَهُ الْبَيَانُ عِنْدَهُمْ قَدِ انْتُقِي"],["وَمَا بِهِ وُجُوهُ تَحْسِينِ الْكَلَامْ","تُعْرَفُ يُدْعَى بِالْبَدِيعِ وَالسَّلَامْ"],["عِلْمٌ بِهِ لِمُقْتَضَى الْحَالِ يُرَى","لَفْظٌ مُطَابِقًا وَفِيهِ ذُكِرَا"],["إِسْنَادُ مُسْنَدٌ إِلَيْهِ مُسْنَدُ","وَمُتَعَلِّقَاتُ فِعْلٍ تُورَدُ"],["قَصْرٌ وَإِنْشَاءٌ وَفَصْلٌ وَصْلٌ اوْ","إِيجَازٌ اطْنَابٌ مُسَاوَاةٌ رَأَوْا"],["اَلْحُكْمُ بِالسَّلْبِ أَوِ الْإِيجَابِ","إِسْنَادُهُمْ وَقَصْدُ ذِي الْخِطَابِ"],["إِفَادَةُ السَّامِعِ نَفْسَ الْحُكْمِ","أَوْ كَوْنَ مُخْبِرٍ بِهِ ذَا عِلْمِ"],["فَأَوَّلٌ فَائِدَةٌ وَالثَّانِي","لَازِمُهَا عِنْدَ ذَوِي الْأَذْهَانِ"],["وَرُبَّمَا أُجْرِيَ مُجْرَى الْجَاهِلِ","مُخَاطَبٌ إِنْ كَانَ غَيْرَ عَامِلِ"],["كَقَوْلِنَا لِعَالِمٍ ذِي غَفْلَةِ","اَلذِّكْرُ مُفْتَاحٌ لِبَابِ الْحَضْرَةِ"],["فَيَنْبَغِي اقْتِصَارُ ذِي الْإِخْبَارِ","عَلَى الْمُفِيدِ خَشْيَةَ الْإِكْثَارِ"],["فَيُخْبِرُ الْخَالِي بِلَا تَوْكِيدِ","مَا لَمْ يَكُنْ فِي الْحُكْمِ ذَا تَرْدِيدِ"],["فَحَسَنٌ وَمُنْكِرُ الْإِخْبَارِ","حَتْمٌ لَهُ بِحَسَبِ الْإِنْكَارِ"],["كَقَوْلِهِ ﴿إِنَّا إِلَيْكُمْ مُرْسَلُونْ﴾","فَزَادَ بَعْدُ مَا اقْتَضَاهُ الْمُنْكِرُونْ"],["لِلَفْظِ الِابْتِدَاءِ ثُمَّ الطَّلَبِ","ثُمَّتَ الِانْكَارِ الثَّلَاثَةَ انْسُبِ"],["وَاسْتَحْسِنِ التَّوْكِيدَ إِنْ لَوَّحْتَ لَهْ","بِخَبَرٍ كَسَائِلٍ فِي الْمَنْزِلَهْ"],["وَأَلْحَقُوا أَمَارَةَ الْإِنْكَارِ بِهْ","كَعَكْسِهِ لِنُكْتَةٍ لَمْ تَشْتَبِهْ"],["بِقَسَمٍ قَدْ إِنَّ لَامِ الِابْتِدَا","وَنُونَيِ التَّوْكِيدِ وَاسْمٍ أُكِّدَا"],["وَالنَّفْيُ كَالْإِثْبَاتِ فِي ذَا الْبَابِ","يَجْرِي عَلَى الثَّلَاثَةِ الْأَلْقَابِ"],["بِإِنْ وَكَانَ لَامٍ اوْ بَاءٍ يَمِينْ","كَمَا جَلِيسُ الْفَاسِقِينَ بِالْأَمِينْ"],["وَلِحَقِيقَةٍ مَجَازٍ وَرَدَا","لِلْعَقْلِ مَنْسُوبَيْنِ أَمَّا الْمُبْتَدَا"],["إِسْنَادُ فِعْلٍ أَوْ مُضَاهِيهِ إِلَى","صَاحِبِهِ كَفَازَ مَنْ تَبَتَّلَا"],["أَقْسَامُهُ مِنْ حَيْثُ الِاعْتِقَادُ","وَوَاقِعٌ أَرْبَعَةٌ تُفَادُ"],["وَالثَّانِ أَنْ يُسْنَدَ لِلْمُلَابَسِ","لَيْسَ لَهُ يُبْنَى كَثَوْبٍ لَابِسِ"],["أَقْسَامُهُ بِحَسَبِ النَّوْعَيْنِ فِي","جُزْأَيْهِ أَرْبَعٌ بِلَا تَكَلُّفِ"],["وَوَجَبَتْ قَرِينَةٌ لَفْظِيَّهْ","أَوْ مَعْنَوِيَّةٌ وَإِنْ عَادِيَّهْ"],["يُحْذَفُ لِلْعِلْمِ وَلَاخْتِبَارِ","مُسْتَمِعٍ وَصِحَّةِ الْإِنْكَارِ"],["سَتْرٍ وَضِيقِ فُرْصَةٍ إِجْلَالِ","وَعَكْسِهِ وَنَظْمٍ اسْتِعْمَالِ"],["كَحَبَّذَا طَرِيقَةُ الصُّوفِيَّهْ","تَهْدِي إِلَى الْمَرْتَبَةِ الْعَلِيَّهْ"],["وَاذْكُرْهُ لِلْأَصْلِ وَالِاحْتِيَاطِ","غَبَاوَةٍ إِيضَاحٍ انْبِسَاطِ"],["تَلَذُّذٍ تَبَرُّكٍ إِعْظَامِ","إِهَانَةٍ تَشَوُّقٍ نِظَامِ"],["تَعَبُّدٍ تَعَجُّبٍ تَهْوِيلِ","تَقْرِيرٍ اوْ إِشْهَادٍ اوْ تَسْجِيلِ"],["وَكَوْنُهُ مُعَرَّفًا بِمُضْمَرِ","بِحَسَبِ الْمَقَامِ فِي النَّحْوِ دُرِي"],["وَالْأَصْلُ فِي الْمُخَاطَبِ التَّعْيِينُ","وَالتَّرْكُ لِلشُّمُولِ مُسْتَبِينُ"],["وَكَوْنُهُ بِعَلَمٍ لِيَحْصُلَا","بِذِهْنِ سَامِعٍ بِشَخْصٍ أَوَّلَا"],["تَبَرُّكٍ تَلَذُّذٍ عِنَايَةِ","إِجْلَالٍ اوْ إِهَانَةٍ كِنَايَةِ"],["وَكَوْنُهُ بِالْوَصْلِ لِلتَّفْخِيمِ","تَقْرِيرٍ اوْ هُجْنَةٍ اوْ تَوْهِيمِ"],["إِيمَاءٍ اوْ تَوَجُّهِ السَّامِعِ لَهْ","أَوْ فَقْدِ عِلْمِ سَامِعٍ غَيْرَ الصِّلَهْ"],["وَبِإِشَارَةٍ لِكَشْفِ الْحَالِ","مِنْ قُرْبٍ اوْ بُعْدٍ أَوِ اسْتِجْهَالِ"],["أَوْ غَايَةِ التَّمْيِيزِ وَالتَّعْظِيمِ","وَالْحَطِّ وَالتَّنْبِيهِ وَالتَّفْخِيمِ"],["وَكَوْنُهُ بِاللَّامِ فِي النَّحْوِ عُلِمْ","لَكِنَّ الِاسْتِغْرَاقَ فِيهِ يَنْقَسِمْ"],["إِلَى حَقِيقِيٍّ وَعُرْفِيٍّ وَفِي","فَرْدٍ مِنَ الْجَمْعِ أَعَمُّ فَاقْتَفِي"],["وَبِإِضَافَةٍ لِحَصْرٍ وَاخْتِصَارْ","تَشْرِيفِ أَوَّلٍ وَثَانٍ وَاحْتِقَارْ"],["تَكَافُؤٍ سَآمَةٍ إِخْفَاءِ","وَحَثٍّ اوْ مَجَازٍ اسْتِهْزَاءِ"],["وَنَكَّرُوا إِفْرَادًا اوْ تَكْثِيرَا","تَنْوِيعًا اوْ تَعْظِيمًا اوْ تَحْقِيرَا"],["كَجَهْلٍ اوْ تَجَاهُلٍ تَهْوِيلِ","تَهْوِينٍ اوْ تَلْبِيسٍ اوْ تَقْلِيلِ"],["وَوَصْفُهُ لِكَشْفٍ اوْ تَخْصِيصِ","ذَمٍّ ثَنَا تَوْكِيدٍ اوْ تَنْصِيصِ"],["وَأَكَّدُوا تَقْرِيرًا اوْ قَصْدَ الْخُلُوصْ","مِنْ ظَنِّ سَهْوٍ أَوْ مَجَازٍ أَوْ خُصُوصْ"],["وَعَطَفُوا عَلَيْهِ بِالْبَيَانِ","بِاسْمٍ بِهِ يَخْتَصُّ لِلْبَيَانِ"],["وَأَبْدَلُوا تَقْرِيرًا اوْ تَحْصِيلَا","وَعَطَفُوا بِنَسَقٍ تَفْصِيلَا"],["لِأَحَدِ الْجُزْأَيْنِ أَوْ رَدٍّ إِلَى","حَقٍّ وَصَرْفَ الْحُكْمِ لِلَّذِي تَلَا"],["وَالشَّكِّ وَالتَّشْكِيكِ وَالْإِبْهَامِ","وَغَيْرِ ذَلِكَ مِنَ الْأَحْكَامِ"],["وَفَصْلُهُ يُفِيدُ قَصْرَ الْمُسْنَدِ","عَلَيْهِ كَالصُّوفِيُّ هُوَّ الْمُهْتَدِي"],["وَقَدَّمُوا لِلْأَصْلِ أَوْ تَشْوِيفِ","لِخَبَرٍ تَلَذُّذٍ تَشْرِيفِ"],["وَحَطٍّ اهْتِمَامٍ اوْ تَنْظِيمِ","تَفَاؤُلٍ تَخْصِيصٍ اوْ تَعْمِيمِ"],["إِنْ صَاحَبَ الْمُسْنَدَ حَرْفُ السَّلْبِ","إِذْ ذَاكَ يَقْتَضِي عُمُومَ السَّلْبِ"],["وَخَرَجُوا عَنْ مُقْتَضَى الظَّوَاهِرِ","كَوَضْعِ مُضْمَرٍ مَكَانَ الظَّاهِرِ"],["لِنُكْتَةٍ كَبَعْثٍ اوْ كَمَالِ","تَمْيِيزٍ اوْ سُخْرِيَةٍ إِجْهَالِ"],["أَوْ عَكْسٍ اوْ دَعْوَى الظُّهُورِ وَالْمَدَدْ","لِنُكْتَةِ التَّمْكِينِ كَاللهُ الصَّمَدْ"],["وَقَصْدِ الِاسْتِعْطَافِ وَالْإِرْهَابِ","نَحْوُ الْأَمِيرُ وَاقِفٌ بِالْبَابِ"],["وَمِنْ خِلَافِ الْمُقْتَضَى صَرْفُ مُرَادْ","ذِي نُطْقٍ اوْ سُؤْلٍ لِغَيْرِ مَا أَرَادْ"],["لِكَوْنِهِ أَوْلَى بِهِ وَأَجْدَرَا","كَقِصَّةِ الْحَجَّاجِ وَالْقَبَعْثَرَى"],["وَالِالْتِفَاتُ وَهْوَ الِانْتِقَالُ مِنْ","بَعْضِ الْأَسَالِيبِ إِلَى بَعْضٍ قَمِنْ"],["وَالْوَجْهُ الِاسْتِجْلَابُ لِلْخِطَابِ","وَنُكْتَةٍ تَخُصُّ بَعْضَ الْبَابِ"],["وَصِيغَةَ الْمَاضِي لِآتٍ أَوْرَدُوا","وَقَلَبُوا لِنُكْتَةٍ وَأَنْشَدُوا"],["وَمَهْمَهٍ مُغْبَرَّةٍ أَرْجَاؤُهُ","كَأَنَّ لَوْنَ أَرْضِهِ سَمَاؤُهُ"],["يُحْذَفُ مُسْنَدٌ لِمَا تَقَدَّمَا","وَالْتَزَمُوا قَرِينَةً لِيُعْلَمَا"],["وَذِكْرُهُ لِمَا مَضَى أَوْ لِيُرَى","فِعْلًا أَوِ اسْمًا فَيُفِيدَ الْمُخْبَرَا"],["وَأَفْرَدُوهُ لِانْعِدَامِ التَّقْوِيَهْ","وَسَبَبٍ كَالزُّهْدُ رَأْسُ التَّزْكِيَهْ"],["وَكَوْنُهُ فِعْلًا فَلِلتَّقْيِيدِ","بِالْوَقْتِ مَعْ إِفَادَةِ التَّجْدِيدِ"],["وَكَوْنُهُ اسْمًا لِلْثُبُوتِ وَالدَّوَامْ","وَقَيَّدُوا كَالْفِعْلِ رَعْيًا لِلتَّمَامْ"],["وَتَرَكُوا تَقْيِيدَهُ لِنُكْتَةٍ","كَسُتْرَةٍ أَوِ انْتِهَازِ فُرْصَةٍ"],["وَخَصَّصُوا بِالْوَصْفِ وَالْإِضَافَهْ","وَتَرَكُوا لِمُقْتَضٍ خِلَافَهْ"],["وَكَوْنُهُ مُعَلَّقًا بِالشَّرْطِ","فَلِمَعَانِي أَدَوَاتِ الشَّرْطِ"],["وَنَكَّرُوا إِتْبَاعًا اوْ تَفْخِيمَا","حَطًّا وَفَقْدَ عَهْدٍ اوْ تَعْمِيمَا"],["وَعَرَّفُوا إِفَادَةً لِلْعِلْمِ","بِنِسْبَةٍ أَوْ لَازِمٍ لِلْحُكْمِ"],["وَقَصَرُوا تَحْقِيقًا اوْ مُبَالَغَهْ","بِعُرْفِ جِنْسِهِ كَهِنْدُ الْبَالِغَهْ"],["وَجُمْلَةً لِسَبَبٍ أَوْ تَقْوِيَهْ","كَالذِّكْرُ يَهْدِي لِطَرِيقِ التَّصْفِيَهْ"],["وَاسْمِيَّةُ الْجُمْلَةِ وَالْفِعْلِيَّهْ","وَشَرْطُهَا لِنُكْتَةٍ جَلِيَّهْ"],["وَأَخَّرُوا أَصَالَةً وَقَدَّمُوا","لِقَصْرِ مَا بِهِ عَلَيْهِ يُحْكَمُ"],["تَنْبِيهٍ اوْ تَفَاؤُلٍ تَشَوُّفِ","كَفَازَ بِالْحَضْرَةِ ذُو تَصَوُّفِ"],["وَالْفِعْلُ مَعْ مَفْعُولِهِ كَالْفِعْلِ مَعْ","فَاعِلِهِ فِيمَا لَهُ مَعْهُ اجْتَمَعْ"],["وَالْغَرَضُ الْإِشْعَارُ بِالتَّلَبُّسِ","بِوَاحِدٍ مِنْ صَاحِبَيْهِ فَائْتَسِ"],["وَغَيْرُ قَاصِرٍ كَقَاصِرٍ يُعَدّْ","مَهْمَا يَكُ الْمَقْصُودُ نِسْبَةً فَقَدْ"],["وَيُحْذَفُ الْمَفْعُولُ لِلتَّعْمِيمِ","وَهُجْنَةٍ فَاصِلَةٍ تَفْهِيمِ"],["مِنْ بَعْدِ إِبْهَامٍ وَلِاخْتِصَارِ","كَبَلَغَ الْمُولَعُ بِالْأَذْكَارِ"],["وَجَاءَ لِلتَّخْصِيصِ قَبْلَ الْفِعْلِ","تَهَمُّمٍ تَبَرُّكٍ وَفَصْلِ"],["وَاحْكُمْ لِمَعْلُولَاتِهِ بِمَا ذُكِرْ","وَالسِّرُّ فِي التَّرْتِيبِ فِيهَا مُشْتَهِرْ"],["تَخْصِيصُ أَمْرٍ مُطْلَقًا بِأَمْرِ","هُوَ الَّذِي يَدْعُونَهُ بِالْقَصْرِ"],["يَكُونُ فِي الْمَوْصُوفِ وَالْأَوْصَافِ","وَهْوَ حَقِيقِيٌّ كَمَا إِضَافِي"],["لِقَلْبٍ اوْ تَعْيِينٍ اوْ إِفْرَادِ","كَإِنَّمَا تَرْقَى بِالِاسْتِعْدَادِ"],["وَأَدَوَاتُ الْقَصْرِ إِلَّا إِنَّمَا","عَطْفٌ وَتَقْدِيمٌ كَمَا تَقَدَّمَا"],["مَا لَمْ يَكُنْ مُحْتَمِلًا لِلصِّدْقِ","وَالْكَذِبِ الْإِنْشَا كَكُنْ بِالْحَقِّ"],["وَالطَّلَبُ اسْتِدْعَاءُ مَا لَمْ يَحْصُلِ","أَقْسَامُهُ كَثِيرَةٌ سَتَنْجَلِي"],["أَمْرٌ وَنَهْيٌ وَدُعَاءٌ وَنِدَا","تَمَنٍّ اسْتِفْهَامٌ أُعْطِيتَ الْهُدَى"],["وَاسْتَعْمَلُوا كَلَيْتَ لَوْ وَهَلْ لَعَلْ","وَحَرْفَ حَضٍّ وَلِلِاسْتِفْهَامِ هَلْ"],["أَيٌّ مَتَى أَيَّانَ أَيْنَ مَنْ وَمَا","وَكَيْفَ أَنَّى كَمْ وَهَمْزٌ عُلِمَا"],["وَالْهَمْزُ لِلتَّصْدِيقِ وَالتَّصَوُّرِ","وَبِالَّذِي يَلِيهِ مَعْنَاهُ حَرِي"],["وَهَلْ لِتَصْدِيقٍ بِعَكْسِ مَا غَبَرْ","وَلَفْظُ الِاسْتِفْهَامِ رُبَّمَا عَبَرْ"],["لِأَمْرٍ اسْتِبْطَاءٍ اوْ تَقْرِيرِ","تَعَجُّبٍ تَهَكُّمٍ تَحْقِيرِ"],["تَنْبِيهٍ اسْتِبْعَادٍ اوْ تَرْهِيبِ","إِنْكَارِ ذِي تَوْبِيخٍ اوْ تَكْذِيبِ"],["وَقَدْ يَجِي أَمْرٌ وَنَهْيٌ وَنِدَا","فِي غَيْرِ مَعْنَاهُ لِأَمْرٍ قُصِدَا"],["وَصِيغَةُ الْأَخْبَارِ تَأْتِي لِلطَّلَبْ","لِفَأْلٍ اوْ حِرْصٍ وَحَمْلٍ وَأَدَبْ"],["اَلْفَصْلُ تَرْكُ عَطْفِ جُمْلَةٍ أَتَتْ","مِنْ بَعْدِ أُخْرَى عَكْسَ وَصْلٍ قَدْ ثَبَتْ"],["فَافْصِلْ لَدَى التَّوْكِيدِ وَالْإِبْدَالِ","لِنُكْتَةٍ وَنِيَّةِ السُّؤَالِ"],["وَعَدَمِ التَّشْرِيكِ فِي حُكْمٍ جَرَى","أَوِ اخْتِلَافٍ طَلَبًا وَخَبَرَا"],["وَفَقْدِ جَامِعٍ وَمَعْ إِيهَامِ","عَطْفٍ سِوَى الْمَقْصُودِ فِي الْكَلَامِ"],["وَصِلْ لَدَى التَّشْرِيكِ فِي الْإِعْرَابِ","وَقَصْدِ رَفْعِ اللَّبْسِ فِي الْجَوَابِ"],["وَفِي اتِّفَاقٍ مَعَ الِاتِّصَالِ","فِي عَقْلٍ اوْ فِي وَهْمٍ اوْ خَيَالِ"],["وَالْوَصْلُ مَعْ تَنَاسُبٍ فِي اسْمٍ وَفِي","فِعْلٍ وَفَقْدِ مَانِعٍ قَدِ اصْطُفِي"],["تَأْدِيَةُ الْمَعْنَى بِلَفْظِ قَدْرِهِ","هِيَ الْمُسَاوَاةُ كَسِرْ بِذِكْرِهِ"],["وَبِأَقَلَّ مِنْهُ إِيجَازٌ عُلِمْ","وَهْوَ إِلَى قَصْرٍ وَحَذْفٍ يَنْقَسِمْ"],["كَعَنْ مَجَالِسِ الْفُسُوقِ بُعْدَا","وَلَا تُصَاحِبْ فَاسِقًا فَتَرْدَى"],["وَعَكْسُهُ يُعْرَفُ بِالْإِطْنَابِ","كَالْزَمْ رَعَاكَ اللهُ قَرْعَ الْبَابِ"],["يَجِيءُ بِالْإِيضَاحِ بَعْدَ اللَّبْسِ","لِشَوْقٍ اوْ تَمَكُّنٍ فِي النَّفْسِ"],["وَجَاءَ بِالْإِيغَالِ وَالتَّذْيِيِلِ","تَكْرِيرٍ اعْتِرَاضٍ اوْ تَكْمِيلِ"],["يُدْعَى بِالِاحْتِرَاسِ وَالتَّتْمِيمِ","وَقَفْوِ ذِي التَّخْصِيصِ ذَا التَّعْمِيمِ"],["وَوَصْمَةُ الْإِخْلَالِ وَالتَّطْوِيلِ","وَالْحَشْوِ مَرْدُودٌ بِلَا تَفْصِيلِ"],["فَنُّ الْبَيَانِ عِلْمُ مَا بِهِ عُرِفْ","تَأْدِيَةُ الْمَعْنَى بِطُرْقٍ مُخْتَلِفْ"],["وُضُوحُهَا وَاحْصُرْهُ فِي ثَلَاثَةِ","تَشْبِيهٍ اوْ مَجَازٍ اوْ كِنَايَةِ"],["وَالْقَصْدُ بِالدَّلَالَةِ الْوَضْعِيَّهْ","عَلَى الْأَصَحِّ الْفَهْمُ لَا الْحَيْثِيَّهْ"],["أَقْسَامُهَا ثَلَاثَةٌ مُطَابَقَهْ","تَضَمُّنٌ الْتِزَامٌ امَّا السَّابِقَهْ"],["فَهْيَ الْحَقِيقَهْ لَيْسَ فِي الْبَيَانِ","بَحْثٌ لَهَا وَعَكْسُهَا الْعَقْلِيَّتَانِ"],["تَشْبِيهُنَا دَلَالَةٌ عَلَى اشْتِرَاكْ","أَمْرَيْنِ فِي مَعْنًى بِآلَةٍ أَتَاكْ"],["أَرْكَانُهُ أَرْبَعَةٌ وَجْهٌ أَدَاهْ","وَطَرَفَاهُ فَاتَّبِعْ سُبْلَ النَّجَاهْ"],["فَصْلٌ وَحِسِّيَّانِ مِنْهُ الطَّرَفَانْ","أَيْضًا وَعَقْلِيَّانِ أَوْ مُخْتَلِفَانْ"],["وَالْوَجْهُ مَا يَشْتَرِكَانِ فِيهِ","وَدَاخِلًا وَخَارِجًا تُلْفِيهِ"],["وَخَارِجٌ وَصْفٌ حَقِيقِيٌّ جَلَا","بِحِسٍّ اوْ عَقْلٍ وَنِسْبِيٌّ تَلَا"],["وَوَاحِدًا يَكُونُ أَوْ مُؤَلَّفَا","أَوْ مُتَعَدِّدًا وَكُلٌّ عُرِفَا"],["بِحِسٍّ اوْ عَقْلٍ وَتَشْبِيهٌ نُمِي","فِي الضِّدِّ لِلتَّلْمِيحِ وَالتَّهَكُّمِ"],["أَدَاتُهُ كَافٌ كَأَنَّ مِثْلُ","وَكُلُّ مَا ضَاهَاهُ ثُمَّ الْأَصْلُ"],["إِيلَاءُ مَا كَالْكَافِ مَا شُبِّهَ بِهْ","بِعَكْسِ مَا سِوَاهُ فَاعْلَمْ وَانْتَبِهْ"],["وَغَايَةُ التَّشْبِيهِ كَشْفُ الْحَالِ","مِقْدَارٍ اوْ إِمَكَانٍ اوْ إِيصَالِ"],["تَزْيِينٌ اوْ تَشْوِيهٌ اهْتِمَامُ","تَنْوِيهٌ اسْتِطْرَافٌ اوْ إِيهَامُ"],["رُجْحَانِهِ فِي الْوَجْهِ بِالْمَقْلُوبِ","كَاللَّيْثُ مِثْلُ الْفَاسِقِ الْمَصْحُوبِ"],["وَبِاعْتِبَارِ طَرَفَيْهِ يَنْقَسِمْ","أَرْبَعَةً تَرْكِيبًا افْرَادًا عُلِمْ"],["وَبِاعْتِبَارِ عَدَدٍ مَلْفُوفٌ اوْ","مَفْرُوقٌ اوْ تَسْوِيَةٌ جَمْعٌ رَأَوْا"],["وَبِاعْتِبَارِ الْوَجْهِ تَمْثِيلٌ إِذَا","مِنْ مُتَعَدِّدٍ تَرَاهُ أُخِذَا"],["وَبِاعْتِبَارِ الْوَجْهِ أَيْضًا مُجْمَلُ","خَفِيٌّ اوْ جَلِيٌّ اوْ مُفَصَّلُ"],["وَمِنْهُ بِاعْتِبَارِهِ أَيْضًا قَرِيبْ","وَهْوَ جَلِيُّ الْوَجْهِ عَكْسُهُ الْغَرِيبْ"],["لِكَثْرَةِ التَّفْصِيلِ أَوْ لِنُدْرَةِ","فِي الذِّهْنِ كَالتَّرْكِيبِ فِي كَنُهْيَةِ"],["وَبِاعْتِبَارِ آلَةٍ مُؤَكَّدُ","بِحَذْفِهَا وَمُرْسَلٌ إِذْ تُوجَدُ"],["وَمِنْهُ مَقْبُولٌ بِغَايَةٍ يَفِي","وَعَكْسُهُ الْمَرْدُودُ وَالتَّعَسُّفِ"],["وَأَبْلَغُ التَّشْبِيهِ مَا مِنْهُ حُذِفْ","وَجْهٌ وَآلَةٌ يَلِيهِ مَا عُرِفْ"],["حَقِيقَةٌ مُسْتَعْمَلٌ فِيمَا وُضِعْ","لَهُ بِعُرْفِ ذِي الْخِطَابِ فَاتَّبِعْ"],["ثُمَّ الْمَجَازُ قَدْ يَجِيءُ مُفْرَدَا","وَقَدْ يَجِي مُرَكَّبًا فَالْمُبْتَدَا"],["كَلِمَةٌ غَابَرَتِ الْمَوْضُوعَ مَعْ","قَرِينَةٍ لِعُلْقَةٍ نِلْتَ الْوَرَعْ"],["كَاخْلَعْ نِعَالَ الْكَوْنِ كَيْ تَرَاهُ","وَغُضَّ طَرْفَ الْقَلْبِ عَنْ سِوَاهُ"],["كِلَاهُمَا شَرْعِيٌّ اوْ عُرْفِيُّ","نَحْوُ ارْتَقَى لِلْحَضْرَةِ الصُّوفِيُّ"],["أَوْ لُغَوِيٌّ وَالْمَجَازُ مُرْسَلُ","أَوِ اسْتِعَارَةٌ فَأَمَّا الْأَوَّلُ"],["فَمَا سِوَى تَشَابُهٍ عَلَاقَتُهْ","جُزْءٌ وَكُلٌّ أَوْ مَحَلٌّ آلَتُهْ"],["ظَرْفٌ وَمَظْرُوفٌ مُسَبَّبٌ سَبَبْ","وَصْفٌ لِمَاضٍ أَوْ مَآلٍ مُرْتَقَبْ"],["وَالِاسْتِعَارَةُ مَجَازٌ عُلْقَتُهْ","تَشَابُهٌ كَأَسَدٍ شَجَاعَتُهْ"],["وَهْيَ مَجَازٌ لُغَةً عَلَى الْأَصَحّْ","وَمُنِعَتْ فِي عَلَمٍ لِمَا اتَّضَحْ"],["وَفَرْدًا اوْ مَعْدُودًا اوْ مُؤَلَّفَا","مِنْهُ قَرِينَةٌ لَهَا قَدْ أُلِفَا"],["وَمَعْ تَنَافِي طَرَفَيْهَا تَنْتَمِي","إِلَى الْعِنَادِ لَا الْوِفَاقِ فَاعْلَمِ"],["ثُمَّ الْعِنَادِيَّةُ تَلْمِيحِيَّهْ","تُلْفَى كَمَا تُلْفَى تَهَكُّمِيَّهْ"],["وَبِاعْتِبَارِ جَامِعٍ قَرِيبَهْ","كَقَمَرٌ يَقْرَأُ أَوْ غَرِيبَهْ"],["وَبِاعْتِبَارِ جَامِعٍ وَطَرَفَيْنِ","حِسًّا وَعَقْلًا سِتَّةٌ بِغَيْرِ مَيْنِ"],["وَاللَّفْظُ إِنْ جِنْسًا فَقُلْ أَصْلِيَّهْ","وَتَبَعِيَّةً لَدَى الْوَصْفِيَّهْ"],["وَالْفِعْلِ وَالْحَرْفِ كَحَالِ الصُّوفِي","يَنْطِقُ أَنَّهُ الْمُنِيبُ الْمُوفِي"],["وَأَطْلَقَتْ وَهْيَ الَّتِي لَمْ تَقْتَرِنْ","بِوَصْفٍ اوْ تَفْرِيعِ أَمْرٍ فَاسْتَبِنْ"],["وَجُرِّدَتْ بِلَائِقٍ بِالْفَصْلِ","وَرُشِّحَتْ بِلَائِقٍ بِالْأَصْلِ"],["نَحْوُ ارْتَقَى إِلَى السَّمَاءِ الْقُدْسِ","فَفَاقَ مَنْ خَلَّفَ أَرْضَ الْحِسِّ"],["أَبْلَغُهَا التَّرْشِيحُ لِابْتِنَائِهْ","عَلَى تَنَاسِي الشِّبْهِ وَانْتِفَائِهْ"],["وَذَاتُ مَعْنًى ثَابِتٍ بِحِسٍّ اوْ","عَقْلٍ فَتَحْقِيقِيَّةٌ كَذَا رَأَوْا"],["كَأَشْرَقَتْ بَصَائِرُ الصُّوفِيَّهْ","بِنُورِ شَمْسِ الْحَضْرَةِ الْقُدْسِيَّهْ"],["وَحَيْثُ تَشْبِيهٌ بِنَفْسٍ أُضْمِرَا","وَمَا سِوَى مُشَبَّهٍ لَمْ يُذْكَرَا"],["وَدَلَّ لَازِمٌ لِمَا شُبِّهَ بِهْ","فَذَلِكَ التَّشْبِيهُ عِنْدَ الْمُنْتَبِهْ"],["يُعْرَفُ بِاسْتِعَارَةِ الْكِنَايَةِ","وَذِكْرُ لَازِمٍ بِتَخْيِيلِيَّةِ"],["كَأَنْشَبَتْ مَنِيَّةٌ أَظْفَارَهَا","وَأَشْرَقَتْ حَضْرَتُهَا أَنْوَارَهَا"],["مُحَسِّنُ اسْتِعَارَةٍ تَدْرِيهِ","بِرَعْيِ وَجْهِ الْحُسْنِ لِلتَّشْبِيهِ"],["وَالْبُعْدُ عَنْ رَائِحَةِ التَّشْبِيهِ فِي","لَفْظٍ وَلَيْسَ الْوَجْهُ أَلْغَازًا قُفِي"],["مُرَكَّبُ الْمَجَازِ مَا تَحَصَّلَا","فِي نِسْبَةٍ أَوْ مِثْلَ تَمْثِيلٍ جَلَا"],["وَإِنْ أَتَى اسْتِعَارَةً مُرَكَّبُ","فَمَثَلًا يُدْعَى وَلَا يُنَكَّبُ"],["وَمِنْهُ مَا إِعْرَابُهُ تَغَيَّرَا","بِحَذْفِ لَفْظٍ أَوْ زِيَادَةٍ تُرَى"],["لَفْظٌ بِهِ لَازِمُ مَعْنَاهُ قُصِدْ","مَعَ جَوَازِ قَصْدِهِ مَعْهُ يَرِدْ"],["إِلَى اخْتِصَاصِ الْوَصْفِ بِالْمَوْصُوفِ","كَالْخَيْرُ فِي الْعُزْلَةِ يَا ذَا الصُّوفِي"],["وَنَفْسِ مَوْصُوفٍ وَوَصْفٍ وَالْغَرَضْ","إِيضَاحٌ اخْتِصَارٌ اوْ صَوْنٌ عَرَضْ"],["أَو انْتِقَاءُ اللَّفْظِ لَاسْتِهْجَانِ","وَنَحْوِهِ كَاللَّمْسِ وَالْإِتْيَانِ"],["ثُمَّ الْمَجَازُ وَالْكُنَى أَبْلَغُ مِنْ","تَصْرِيحٍ اوْ حَقِيقَةٍ كَذَا زُكِنْ"],["فِي الْفَنِّ تَقْدِيمُ اسْتِعَارَةٍ عَلَى","تَشْبِيهٍ ايْضًا بِاتِّفَاقِ الْعُقَلَا"],["عِلْمٌ بِهِ وُجُوهُ تَحْسِينِ الْكَلَامْ","يُعْرَفُ بَعْدَ رَعْيِ سَابِقِ الْمَرَامْ"],["ثُمَّ وُجُوهُ حُسْنِهِ ضَرْبَانِ","بِحَسَبِ الْأَلْفَاظِ وَالْمَعَانِي"],["وَعُدَّ مِنْ أَلْقَابِهِ الْمُطَابَقَهْ","تَشَابُهُ الْأَطْرَافِ وَالْمُوَافَقَهْ"],["وَالْعَكْسُ وَالتَّسْهِيمُ وَالْمُشَاكَلَهْ","تَزَاوُجٌ رُجُوعٌ اوْ مُقَابَلَهْ"],["تَوْرِيَةٌ تُدْعَى بِإِيهَامٍ لِمَا","أُرِيدَ مَعْنَاهُ الْبَعِيدُ مِنْهُمَا"],["وَرُشِّحَتْ بِمَا يُلَائِمُ الْقَرِيبْ","وَجُرِّدَتْ بِفَقْدِهِ فَكُنْ مُنِيبْ"],["جَمْعٌ وَتَفْرِيقٌ وَتَقْسِيمٌ وَمَعْ","كِلَيْهِمَا أَوْ وَاحِدٍ جَمْعٌ يَقَعْ"],["وَاللَّفُّ وَالنَّشْرُ وَالِاسْتِخْدَامُ","أَيْضًا وَتَجْرِيدٌ لَهُ أَقْسَامُ"],["ثُمَّ الْمُبَالَغَةُ وَصْفٌ يُدَّعَى","بُلُوغُهُ قَدْرًا يُرَى مُمْتَنِعَا"],["أَوْ نَائِيًا وَهْوَ عَلَى أَنْحَاءِ","تَبْلِيغٌ اغْرَاقٌ غُلُوٌّ جَائِي"],["مَقْبُولًا اوْ مَرْدُودًا التَّفْرِيعُ","وَحُسْنُ تَعْلِيلٍ لَهُ تَنْوِيعُ"],["وَقَدْ أَتَوْا فِي الْمَذْهَبِ الْكَلَامِي","بِحُجَجٍ كَمَهْيَعِ الْكَلَامِ"],["وَأَكَّدُوا مَدْحًا بِشِبْهِ الذَّمِّ","كَالْعَكْسِ وَالْإِدْمَاجُ مِنْ ذَا الْعِلْمِ"],["وَجَاءَ الِاسْتِتْبَاعُ وَالتَّوْجِيهُ مَا","يَحْتَمِلُ الْوَجْهَيْنِ عِنْدَ الْعُلَمَا"],["وَمِنْهُ قَصْدُ الْجَدِّ بِالْهَزْلِ كَمَا","يُثْنَى عَلَى الْفَخُورِ ضِدَّ مَا اعْتَمَا"],["وَسَوْقُ مَعْلُومٍ مَسَاقَ مَا جُهِلْ","لِنُكْتَةٍ تَجَاهُلٌ عَنْهُمْ نُقِلْ"],["وَالْقَوْلُ بِالْمُوجَبِ قُلْ ضَرْبَانِ","كِلَاهُمَا فِي الْفَنِّ مَعْلُومَانِ"],["وَالِاطِّرَادُ الْعَطْفُ بِالْآبَاءِ","لِلشَّخْصِ مُطْلَقًا عَلَى الْوِلَاءِ"],["مِنْهُ الْجِنَاسُ وَهْوَ ذُو تَمَامِ","مَعَ اتِّحَادِ الْحَرْفِ وَالنِّظَامِ"],["وَمُتَمَاثِلًا دُعِي إِنِ ائْتَلَفْ","نَوْعًا وَمُسْتَوْفًى إِذَا النَّوْعُ اخْتَلَفْ"],["لَنْ يَعْرِفَ الْوَاحِدَ إِلَّا وَاحِدَا","فَاخْرُجْ عَنِ الْكَوْنِ تَكُنْ مُشَاهِدَا"],["وَمِنْهُ ذُو التَّرْكِيبِ ذُو تَشَابُهِ","خَطًّا وَمَفْرُوقٌ بِلَا تَشَابُهِ"],["وَإِنْ بِهَيْئَةِ الْحُرُوفِ اخْتَلَفَا","فَهْوَ الَّذِي يَدْعُونَهُ الْمُحَرَّفَا"],["وَنَاقِصٌ مَعَ اخْتِلَافٍ فِي الْعَدَدْ","وَشَرْطُ خُلْفِ النَّوْعِ وَاحِدٌ فَقَدْ"],["وَمَعْ تَقَارُبٍ مُضَارِعًا أُلِفْ","وَمَعْ تَبَاعُدٍ بِلَاحِقٍ وُصِفْ"],["وَهْوَ جِنَاسُ الْقَلْبِ حَيْثُ يَخْتَلِفْ","تَرْتِيبُهَا لِلْكُلِّ وَالْبَعْضِ أَضِفْ"],["مُجَنَّحًا يُدْعَى إِذَا تَقَاسَمَا","بَيْتًا فَكَانَ فَاتِحًا وَخَاتِمَا"],["وَمَعْ تَوَالِي الطَّرَفَيْنِ عُرِفَا","مُزْدَوِجًا كُلُّ جِنَاسٍ أُلِفَا"],["تَنَاسُبُ اللَّفْظَيْنِ فِي اشْتِقَاقِ","وَشِبْهِهِ فَذَاكَ ذُو الْتِحَاقِ"],["وَيَرِدُ التَّجْنِيسُ بِالْإِشَارَةِ","مِنْ غَيْرِ أَنْ يُذْكَرَ فِي الْعِبَارَةِ"],["وَمِنْهُ رَدُّ عَجُزِ اللَّفْظِ عَلَى","صَدْرٍ فَفِي نَثْرٍ بِفَقْرَةٍ جَلَا"],["مُكْتَنِفًا وَالنَّظْمِ الَاوَّلْ أَوَّلَا","آخِرَ مِصْرَاعٍ فَمَا قَبْلُ تَلَا"],["مُكَرَّرًا مُجَانِسًا وَمَا الْتَحَقْ","يَأْتِي كَ﴿تَخْشَى النَّاسَ وَاللهُ أَحَقّْ﴾"],["وَالسَّجْعُ فِي فَوَاصِلٍ فِي النَّثْرِ","مُشْبِهَةً قَافِيَةً فِي الشِّعْرِ"],["ضُرُوبُهُ ثَلَاثَةٌ فِي الْفَنِّ","مُطَرَّفٌ مَعَ اخْتِلَافِ الْوَزْنِ"],["مُرَصَّعٌ إِنْ كَانَ مَا فِي الثَّانِيَهْ","أَوْ جُلُّهُ عَلَى وِفَاقِ الْمَاضِيَهْ"],["وَمَا سِوَاهُ الْمُتَوَازِي فَادْرِي","كَسُرُرٍ مَرْفُوعَةٍ فِي الذِّكْرِ"],["أَبْلَغُ ذَاكَ مُسْتَوٍ فَمَا تُرَى","أُخْرَى الْقَرِينَتَيْنِ فِيهِ أَكْثَرَا"],["وَالْعَكْسُ إِنْ يَكْثُرْ فَلَيْسَ يَحْسُنُ","وَمُطْلَقًا إِعْجَازُهَا تُسَكَّنُ"],["وَجَعْلُ سَجْعِ كُلِّ شَطْرٍ غَيْرَمَا","فِي الْآخَرِ التَّشْطِيرُ عِنْدَ الْعُلَمَا"],["ثُمَّ الْمُوَازَنَةُ وَهْيَ التَّسْوِيَهْ","لِفَاصِلٍ فِي الْوَزْنِ لَا فِي التَّقْفِيَهْ"],["وَهْيَ الْمُمَاثَلَةُ حَيْثُ يَتَّفِقْ","فِي الْوَزْنِ لَفْظُ فَقْرَتَيْهَا فَاسْتَفِقْ"],["وَالْقَلْبُ وَالتَّشْرِيعُ وَالْتِزَامُ مَا","قَبْلَ الرَّوِيِّ ذِكْرُهُ لَنْ يَلْزَمَا"],["وَأَخْذُ شَاعِرٍ كَلَامًا سَبَقَهْ","هُوَ الَّذِي يَدْعُونَهُ بِالسَّرِقَهْ"],["وَكُلُّ مَا قُرِّرَ فِي الْأَلْبَابِ","أَوْ عَادَةٍ فَلَيْسَ مِنْ ذَا الْبَابِ"],["وَالسَّرِقَاتُ عَنْدَهُمْ قِسْمَانِ","خَفِيَّةٌ جَلِيَّةٌ وَالثَّانِي"],["تَضَمُّنُ الْمَعْنَى جَمِيعًا مُسْجَلَا","أَرْدَؤُهُ انْتِحَالُ مَا قَدْ نُقِلَا"],["بِحَالِهِ وَأَلْحَقُوا الْمُرَادِفَا","بِهِ وَيُدْعَى مَا أَتَى مُخَالِفَا"],["لِنَظْمِهِ إِغَارَةً وَحُمِدَا","حَيْثُ مِنَ السَّابِقِ كَانَ أَجْوَدَا"],["وَأَخْذُهُ الْمَعْنَى مُجَرَّدًا دُعِي","سَلْخًا وَإِلْمَامًا وَتَقْسِيمًا فَعِي"],["وَمَا سِوَى الظَّاهِرِ أَنْ يُغَيَّرَا","مَعْنًى بِوَجْهٍ مَا وَمَحْمُودًا يُرَى"],["لِنَقْلٍ اوْ خَلْطٍ شُمُولِ الثَّانِي","وَقَلْبٍ اوْ تَشَابُهِ الْمَعَانِي"],["أَحْوَالُهُ بِحَسَبِ الْخَفَاءِ","تَفَاضَلَتْ فِي الْحُسْنِ وَالثَّنَاءِ"],["وَالِاقْتِبَاسُ أَنْ يُضَمَّنَ الْكَلَامْ","قُرْآنًا اوْ حَدِيثَ سَيِّدِ الْأَنَامْ"],["وَالِاقْتِبَاسُ عِنْدَهُمْ ضَرْبَانِ","مُحَوَّلٌ وَثَابِتُ الْمَعَانِي"],["وَجَائِزٌ لِوَزْنٍ اوْ سِوَاهُ","تَغْيِيرُ نَزْرِ اللَّفْظِ لَا مَعْنَاهُ"],["وَالْأَخْذُ مِنْ شِعْرٍ بِعَزْوِ مَا خَفِي","تَضْمِينُهُمْ وَمَا عَلَى الْأَصْلِ يَفِي"],["بِنُكْتَةٍ أَجَلُّهُ وَاغْتُفِرَا","يَسِيرُ تَغْيِيرٍ وَمَا مِنْهُ يُرَى"],["بَيْتًا فَأَعْلَى بِاسْتِعَانَةٍ عُرِفْ","وَشَطْرًا اوْ أَدْنَى بِإِيدَاعٍ أُلِفْ"],["وَالْعَقْدُ نَظْمُ النَّثْرِ لَا بِالِاقْتِبَاسْ","وَالْحَلُّ نَثْرُ النَّظْمِ فَاعْرِفِ الْقِيَاسْ"],["وَاشْتَرَطُوا الشُّهْرَةَ فِي الْكَلَامِ","وَالْمَنْعُ أَصْلُ مَذْهَبِ الْإِمَامِ"],["إِشَارَةٌ لِقِصَّةٍ شِعْرٍ مَثَلْ","مِنْ غَيْرِ ذِكْرِهِ فَتَلْمِيحٌ كَمُلْ"],["مِنْ ذَلِكَ التَّوْشِيعُ وَالتَّرْدِيدُ","تَرْتِيبٌ اخْتِرَاعٌ اوْ تَعْدِيدُ"],["كَ﴿التَّائِبُونَ الْعَابِدُونَ الْحَامِدُونْ","اَلسَّائِحُونَ الرَّاكِعُونَ السَّاجِدُونْ﴾"],["تَطْرِيزٌ اوْ تَدْبِيجٌ اسْتِشْهَادُ","إِيضَاحٌ ائْتِلَافٌ اسْتِطْرَادُ"],["إِحَالَةٌ تَلْوِيحٌ اوْ تَخْيِيلُ","وَفُرْصَةٌ تَسْمِيطٌ اوْ تَعْدِيلُ"],["تَحْلِيَةٌ أَوْ نَفْلٌ اوْ تَخَتُّمُ","تَجْرِيدٌ اسْتِقْلَالٌ اوْ تَهَكُّمُ"],["تَعْرِيضٌ اوْ إِلْغَازٌ ارْتِقَاءُ","تَنْزِيلٌ اوْ تَأْنِيسٌ اوْ إِيمَاءُ"],["حُسْنُ الْبَيَانِ وَصْفٌ اوْ مُرَاجَعَهْ","حُسْنُ تَخَلُّصٍ بِلَا مُنَازَعَهْ"],["وَلَيْسَ فِي الْإِيهَامِ وَالتَّهَكُّمِ","وَلَا التَّغَالِي بِسِوَى الْمُحَرَّمِ"],["مِنْ كَذِبٍ وَفِي الْمِزَاحِ قَدْ لَزِبْ","بِحَيْثُ لَا مَنْدُوحَةٌ عَنِ الْكَذِبْ"],["وَيَنْبَغِي لِصَاحِبِ الْكَلَامِ","تَأَنُّقٌ فِي الْبَدْءِ وَالْخِتَامِ"],["بِمَطْلَعٍ حَسَنٍ وَحُسْنِ الْفَالِ","وَسَبْكٍ اوْ بَرَاعَةِ اسْتِهْلَالِ"],["وَالْحُسْنُ فِي تَخَلُّصٍ أَوِ اقْتِضَابْ","وَفِي الَّذِي يَدْعُونَهُ فَصْلَ الْخِطَابْ"],["وَمِنْ سِمَاتِ الْحُسْنِ فِي الْخِتَامِ","إِرْدَافُهُ بِمُشْعِرِ التَّمَامِ"],["هَذَا تَمَامُ الْجُمْلَةِ الْمَقْصُودَهْ","مِنْ صَنْعَةِ الْبَلَاغَةِ الْمَحْمُودَهْ"],["ثُمَّ صَلَاةُ اللهِ طُولَ الْأَمَدِ","عَلَى النَّبِيِّ الْمُصْطَفَى مُحَمَّدِ"],["وَآلِهِ وَصَحْبِهِ الْأَخْيَارِ","مَا غَرَّدَ الْمُشْتَاقُ بِالْأَسْحَارِ"],["وَخَرَّ سَاجِدًا إِلَى الْأَذْقَانِ","يَبْغِي وَسِيلَةً إِلَى الرَّحْمَنِ"],["تَمَّ بِشَهْرِ الْحِجَّةِ الْمَيْمُونِ","مُتِمِّ نِصْفِ عَاشِرِ الْقُرُونِ"]],"secs":{"1":"خُطْبَةُ الْكِتَابِ","25":"الْمُقَدِّمَةُ","32":"الْفَنُّ الْأَوَّلُ: عِلْمُ الْمَعَانِي","35":"الْبَابُ الْأَوَّلُ: أَحْوَالُ الْإِسْنَادِ الْخَبَرِيِّ","50":"فَصْلٌ فِي الْإِسْنَادِ الْعَقْلِيِّ","56":"الْبَابُ الثَّانِي: فِي الْمُسْنَدِ إِلَيْهِ","86":"فَصْلٌ: فِي الْخُرُوجِ عَنْ مُقْتَضَى الظَّاهِرِ","96":"الْبَابُ الثَّالِثُ: الْمُسْنَدُ","111":"الْبَابُ الرَّابِعُ: فِي مُتَعَلَّقَاتِ الْفِعْلِ","118":"الْبَابُ الْخَامِسُ: الْقَصْرُ","122":"الْبَابُ السَّادِسُ: فِي الْإِنْشَاءِ","133":"الْبَابُ السَّابِعُ:الْفَصْلُ وَالْوَصْلُ","140":"الْبَابُ الثَّامِنُ: الْإِيجَازُ وَالْإِطْنَابُ وَالْمُسَاوَاةُ","148":"الْفَنُّ الثَّانِي:عِلْمُ الْبَيَانِ","150":"فَصْلٌ فِي الدَّلالَةِ الْوَضْعِيَّةِ","153":"الْبَابُ الأَوَّلُ:التَّشْبِيهُ","160":"فَصْلٌ فِي أَدَاةِ التَّشْبِيهِ وَغَايَتِهِ وَأَقْسَامِهِ","174":"الْبَابُ الثَّانِي: الْحَقِيقَةُ وَالْمَجَازُ","182":"فَصْلٌ فِي الِاسْتِعَارَاتِ","195":"فَصْلٌ: فِي الِاسْتِعَارَةِ التَّحْقِيقِيَّةِ وَالْعَقْلِيَّةِ","197":"فَصْلٌ: فِي الْمَكْنِيَّةِ","201":"فَصْلٌ: فِي تَحْسِينِ الِاسْتِعَارَةِ","203":"فَصْلٌ: فِي تَرْكِيبِ الْمَجَازِ","205":"فَصْلٌ: فِي تَغْيِيرِ الْإِعْرَابِ","206":"الْبَابُ الثَّالِثُ: الْكِنَايَةُ","210":"فَصْلٌ: فِي مَرَاتِبِ الْمَجَازِ وَالْكُنَى","212":"الفَنُّ الثَّالِثُ: عِلْمُ الْبَدِيعِ","214":"الضَرْبُ الْأَوَّلُ: الْمَعْنَوِيُّ","230":"الضَّرْبُ الثَّانِي:اللَّفْظِيُّ","245":"فَصْلٌ: فِي السَّجْعِ","252":"فَصْلٌ: فِي الْمُوَازَنَةِ","255":"السَّرِقَاتُ","262":"السَّرِقَاتُ الْخَفِيَّةُ","265":"الِاقْتِبَاسُ","268":"التَّضْمِينُ وَالْحَلُّ وَالْعَقْدُ","273":"التَّلْمِيحُ","274":"تَذْنِيبٌ فِي أَلْقَابٍ مِنَ الْفَنِّ","281":"فَصْلٌ فِيمَا لَا يُعَدُّ كَذِبًا","283":"خَاتِمَةٌ"}}],"sharh":false};
